describe('Filter list by multiple statuses simultaneously', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="status-filter"]').should('be.visible');
  });

  it('should filter list by selecting multiple status checkboxes', () => {
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-pending"]').click();

    cy.get('[data-testid="apply-filter"]').click();

    cy.get('[data-testid="list-item"]').each(($item) => {
      cy.wrap($item).should(($el) => {
        const status = $el.attr('data-status');
        expect(['active', 'pending']).to.include(status);
      });
    });
  });

  it('should display all items when no status filters are selected', () => {
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-pending"]').click();
    cy.get('[data-testid="apply-filter"]').click();

    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-pending"]').click();
    cy.get('[data-testid="apply-filter"]').click();

    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
  });

  it('should update list count when multiple statuses are selected', () => {
    cy.get('[data-testid="filter-count"]').then(($count) => {
      const initialCount = parseInt($count.text());

      cy.get('[data-testid="status-filter-active"]').click();
      cy.get('[data-testid="status-filter-completed"]').click();
      cy.get('[data-testid="apply-filter"]').click();

      cy.get('[data-testid="filter-count"]').should(($newCount) => {
        const newCountValue = parseInt($newCount.text());
        expect(newCountValue).to.be.lessThan(initialCount);
      });
    });
  });

  it('should handle edge case with single status selection', () => {
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="apply-filter"]').click();

    cy.get('[data-testid="list-item"]').each(($item) => {
      cy.wrap($item).should('have.attr', 'data-status', 'active');
    });
  });

  it('should persist filter selections when toggling between statuses', () => {
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-active"]').should('be.checked');

    cy.get('[data-testid="status-filter-pending"]').click();
    cy.get('[data-testid="status-filter-active"]').should('be.checked');
    cy.get('[data-testid="status-filter-pending"]').should('be.checked');

    cy.get('[data-testid="apply-filter"]').click();
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
  });
});
